import sqlite3

def registrar_consulta(endpoint, resposta):
    conexao = sqlite3.connect(':memory:')
    cursor = conexao.cursor()
    cursor.execute(
        'CREATE TABLE historico (id INTEGER PRIMARY KEY, endpoint TEXT, data_hora TEXT, resposta TEXT)'
    )
    cursor.execute(
        'INSERT INTO historico (endpoint, data_hora, resposta) VALUES (?, ?, ?)',
        (endpoint, '2024-09-30 12:00:00', resposta),
    )
    conexao.commit()
    return cursor.execute('SELECT endpoint, resposta FROM historico').fetchall()

